    importConfig: {
        parameters: {
            query?: {
                /** @description `1` or `true`: validate, plan and diff without applying anything. The answer carries the whole-file upstream `plan` (C9), a deterministic `importDigest` and the counts-only `upstream` summary. */
                dryRun?: "1" | "true";
                /** @description `replace` wipes stores before applying; default is merge. */
                mode?: "merge" | "replace";
                /** @description The digest a dry-run returned. A commit re-plans under the authoritative lock and answers 409 `import_stale` when the upstream document changed since the plan was computed. */
                importDigest?: string;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": components["schemas"]["ConfigBackup"];
            };
        };
        responses: {
            /** @description Configuration imported (or, with dryRun, planned). The upstream section is reported as counts only. */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "mode": "merge",
                     *       "ok": true,
                     *       "upstream": {
                     *         "cleared": 0,
                     *         "omitted": 1,
                     *         "preserved": 1,
                     *         "requiresReplacement": 0
                     *       }
                     *     }
                     */
                    "application/json": components["schemas"]["ConfigImportResult"];
                };
            };
            /** @description Malformed request. Upstream-section schema violations are STRUCTURED JSON (`UpstreamImportRefusal`, validated before any store is touched): `invalid_credential_state` — a v2 entry carries a missing or unrecognized `credentialState` (the offending entry `index` is named; the value is never echoed); `invalid_upstream_credentials_marker` — a `upstream_proxies_v2` section without the exact `upstream_credentials: "omitted"` marker; `schema_mismatch` — a v2 section under a backup version other than 2, a legacy `upstreamProxies` list outside version 1 or carrying the marker, or a marker without the section; `invalid_entry`, `duplicate_id`, `ambiguous_upstream_sections`, `credentials_not_importable`. Other malformed input (invalid JSON, unsupported version) stays plain text. */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    /**
                     * @example {
                     *       "code": "invalid_credential_state",
                     *       "error": "invalid upstream proxies: invalid_credential_state at entry 1: credentialState must be one of none, configured, unusable, mismatch, requiresReplacement",
                     *       "index": 1
                     *     }
                     */
                    "application/json": components["schemas"]["UpstreamImportRefusal"];
                    /** @example unsupported backup version */
                    "text/plain": string;
                };
            };
            403: components["responses"]["PlainForbidden"];
            /** @description `credential_clear_required` — the import would remove, replace or change the authority of a parent proxy that HOLDS a credential or is in the durable `requiresReplacement` state (the marker is resolved only by the Tier-2 replace / Tier-3 clear credential endpoint, never by an import); the complete plan is attached and NOTHING was mutated. `import_stale` — the echoed importDigest no longer matches the document. `document_rejected` — the stored upstream document is rejected. */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": components["schemas"]["UpstreamImportRefusal"];
                };
            };
        };
    };
