    pacProfileLifecycle: {
        parameters: {
            query?: never;
            header?: never;
            path: {
                name: string;
            };
            cookie?: never;
        };
        requestBody: {
            content: {
                "application/json": {
                    /** @enum {string} */
                    action: "save_draft" | "publish" | "rollback" | "repair" | "acknowledge_history_reset";
                    /** @description 2F-A — publish/rollback with NO active profile must echo the collection token instead. */
                    collectionEtag?: string;
                    /** @description 2F-B — echoes the bound challenge when publish/rollback introduces new DIRECT paths. */
                    confirm?: components["schemas"]["PACConfirm"];
                    /**
                     * Format: int64
                     * @description 2F-A — save_draft on an existing draft must echo the loaded draftRevision.
                     */
                    draftRevision?: number;
                    /**
                     * Format: int64
                     * @description 2F-A — publish/rollback must echo the active profile's revision (refusal key `revision`).
                     */
                    expectedActiveRevision?: number;
                    /** @description 2F-B correction — acknowledge_history_reset binds the admin's acknowledgement of a lost node-local history to the active ProfileSpecDigest reviewed (together with expectedActiveRevision); a mismatch is refused `409 history_reset_stale` with `current`. */
                    expectedActiveSpecDigest?: string;
                    /**
                     * Format: uuid
                     * @description 2F-B — required for publish, rollback, repair and acknowledge_history_reset. Decisions are at-most-once: a repeated operationId returns the recorded result (status and body) without committing again.
                     */
                    operationId?: string;
                    /**
                     * @description 2F-B repair — records the OBSERVED active profile as a repaired revision; never rewrites the active store.
                     * @enum {string}
                     */
                    resolution?: "accept_active";
                } & {
                    [key: string]: unknown;
                };
            };
        };
        responses: {
            /** @description Lifecycle action result. publish: `{published:true, operationId, revision, activeRevision, activeSpecDigest, digest, draftRevision, historyState: recorded|pending_reconciliation, scope}`; rollback: `{rolledBack:true, toRevision, newRevision, …}`; repair: `{repaired:true, revision, …}`; acknowledge_history_reset: `{acknowledged:true, operationId, activeRevision, activeSpecDigest, historyState: recorded}`. `historyState: pending_reconciliation` means the active profile IS committed but one of its node-local post-commit effects (history revision, config version keyed by operationId, cluster publication, success audit, terminal record) is not yet durable and will be completed — never duplicated — by reconciliation (next GET, operation or restart); it never means "not published". */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                };
            };
            400: components["responses"]["PlainBadRequest"];
            403: components["responses"]["PlainForbidden"];
            /** @description Unknown rollback target / no history. Body is plain text. */
            404: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "text/plain": string;
                };
            };
            /** @description Structured, keyed by `code`: `stale` (2F-A fence, see PACFenceRefusal), `confirm_required` (candidate-bound DIRECT challenge: `challenge`, `confirmValue`, `binding`), `challenge_stale` (the reviewed candidate changed: `changed` names the fields, a fresh challenge is included), `operation_pending` (a previous intent could not be persisted after reconciliation), `not_ambiguous` / `active_absent` (repair), `history_reset` (the node-local history file was corrupt and quarantined; the ACTIVE profile is untouched but publish/rollback are refused until an admin acknowledges the loss with `acknowledge_history_reset` bound to `current.revision` + `current.activeSpecDigest`), `history_reset_stale` (the acknowledgement named a different active revision/digest; `current` + `changed`), `not_history_reset` (nothing to acknowledge). */
            409: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                };
            };
            428: components["responses"]["PACPreconditionRequired"];
            /** @description `outcome_unknown` (the active write could not be proven; the intent is retained as pending) or `active_write_failed` (proven failure, aborted). */
            500: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                };
            };
            /** @description `lifecycle_ambiguous` — a previous operation's outcome could not be classified from the authoritative active state; publish/rollback are refused until an admin repair with resolution `accept_active`. */
            503: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        [key: string]: unknown;
                    };
                };
            };
        };
    };
